package com.pranit.productsupport.core.service;
import com.pranit.productsupport.contracts.PaymentCapturedEvent;import com.pranit.productsupport.core.domain.*;import com.pranit.productsupport.core.repository.*;import java.time.Instant;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentTransactionService {
 private final ServiceQuoteRepository quotes;private final PaymentRepository payments;private final AppUserRepository users;private final OutboxService outbox;
 public PaymentTransactionService(ServiceQuoteRepository q,PaymentRepository p,AppUserRepository u,OutboxService o){quotes=q;payments=p;users=u;outbox=o;}
 @Transactional public Payment start(Long quoteId,Long customerId,String provider){ServiceQuote q=quotes.findForPayment(quoteId,customerId).orElseThrow(()->ApiException.notFound("Quote not found"));if(!"OPEN".equals(q.getStatus())||q.getExpiresAt().isBefore(Instant.now()))throw ApiException.conflict("Quote is no longer payable");var active=payments.findFirstByQuote_IdAndStatusOrderByCreatedAtDesc(quoteId,"PENDING");if(active.isPresent())return active.get();var initiating=payments.findFirstByQuote_IdAndStatusOrderByCreatedAtDesc(quoteId,"INITIATING");if(initiating.isPresent())throw ApiException.conflict("Payment initiation is already in progress; retry shortly");return payments.saveAndFlush(new Payment(q,provider));}
 @Transactional public Payment attachOrder(Long paymentId,String orderId){Payment p=payments.findById(paymentId).orElseThrow(()->ApiException.notFound("Payment not found"));p.attachOrder(orderId);return p;}
 @Transactional public void markFailed(Long paymentId){payments.findById(paymentId).ifPresent(Payment::fail);}
 @Transactional public boolean captureByOrder(String provider,String orderId,String paymentId){Payment p=payments.findByProviderAndProviderOrderId(provider,orderId).orElseThrow(()->ApiException.notFound("Payment order not found"));if("CAPTURED".equals(p.getStatus())||"DUPLICATE_CAPTURE".equals(p.getStatus()))return false;if("PAID".equals(p.getQuote().getStatus())){p.markDuplicateCapture(paymentId);outbox.enqueue("DuplicatePaymentCaptureDetected",p.getId().toString(),java.util.Map.of("paymentId",p.getId(),"quoteId",p.getQuote().getId(),"providerOrderId",orderId,"providerPaymentId",paymentId,"actionRequired","reconcile_and_refund_if_confirmed"));return true;}p.capture(paymentId);p.getQuote().markPaid();outbox.enqueue("PaymentCaptured",p.getId().toString(),new PaymentCapturedEvent(p.getId(),p.getQuote().getId(),p.getQuote().getTicket().getId(),p.getAmountPaise(),p.getCurrency(),Instant.now()));return true;}
 @Transactional public Payment captureMock(Long paymentId,Long callerId){Payment p=payments.findById(paymentId).orElseThrow(()->ApiException.notFound("Payment not found"));if(!p.getQuote().getTicket().getCustomer().getId().equals(callerId))throw ApiException.notFound("Payment not found");if(!"MOCK".equals(p.getProvider()))throw new ApiException(HttpStatus.BAD_REQUEST,"Only local mock payments can be captured through this endpoint");if(!"CAPTURED".equals(p.getStatus())){p.capture("pay_mock_"+paymentId);p.getQuote().markPaid();outbox.enqueue("PaymentCaptured",p.getId().toString(),new PaymentCapturedEvent(p.getId(),p.getQuote().getId(),p.getQuote().getTicket().getId(),p.getAmountPaise(),p.getCurrency(),Instant.now()));}return p;}
}
